def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit from s_in to s_out"""
    # Find first difference
    pos = -1
    for i, (c1, c2) in enumerate(zip(s_in, s_out)):
        if c1 != c2:
            pos = i
            break

    if pos == -1:
        # Strings are same length but may have different endings
        if len(s_in) > len(s_out):
            return (s_in[len(s_out):], "", len(s_out))
        elif len(s_in) < len(s_out):
            return ("", s_out[len(s_in):], len(s_in))
        else:
            return ("", "", -1)  # No difference

    # Get substring from position to end
    old_sub = s_in[pos:]
    new_sub = s_out[pos:]

    # Find what we're actually changing
    # Check if we're inserting or deleting
    if len(old_sub) > len(new_sub):
        # Deletion
        old_part = old_sub[:len(new_sub)]
        new_part = new_sub
        return (old_part, new_part, pos)
    else:
        # Insertion or substitution
        old_part = old_sub
        new_part = new_sub
        return (old_part, new_part, pos)

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a changed pair"""
    # Simple approach: look for common patterns
    # We'll start with the most specific and move to more general

    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # For now, let's create a simple set of candidates
    candidates = []

    # Most specific: exact substring match
    if pos >= 0 and old_sub:
        candidates.append((old_sub, new_sub))

    # Generalize by removing characters from the beginning or end
    if len(old_sub) > 1:
        candidates.append((old_sub[:-1], new_sub[:-1] if len(new_sub) > 1 else new_sub))
        candidates.append((old_sub[1:], new_sub[1:] if len(new_sub) > 1 else new_sub))

    # Also consider replacing a single character if possible
    if len(old_sub) == 1 and len(new_sub) == 1:
        candidates.append((old_sub, new_sub))

    # Remove duplicates while preserving order
    seen = set()
    unique_candidates = []
    for cand in candidates:
        if cand not in seen:
            seen.add(cand)
            unique_candidates.append(cand)

    return unique_candidates

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings"""
    results = []
    for s in strings:
        new_s = s
        for pattern, replacement in rules:
            new_s = new_s.replace(pattern, replacement)
        results.append(new_s)
    return results

def score_rules(inputs, outputs, rules):
    """Score how well rules perform on the corpus"""
    results = apply_rules(inputs, rules)
    correct = sum(1 for r, o in zip(results, outputs) if r == o)
    return correct / len(outputs)

def find_over_applications(inputs, outputs, rules):
    """Find if any rules over-apply to unchanged pairs"""
    # Apply rules to all inputs
    results = apply_rules(inputs, rules)

    # Check which pairs changed when they shouldn't
    over_apps = []
    for i, (inp, outp, res) in enumerate(zip(inputs, outputs, results)):
        if inp != outp and res == outp:
            # This input was supposed to change but didn't
            pass
        elif inp == outp and res != outp:
            # This input wasn't supposed to change but did
            over_apps.append((i, inp, res))

    return over_apps

def simulate_rule_chain(s, rules):
    """Simulate what happens to a string through each rule"""
    trace = []
    current = s
    for pattern, replacement in rules:
        prev = current
        current = current.replace(pattern, replacement)
        trace.append({
            'rule': f"replace('{pattern}', '{replacement}')",
            'before': prev,
            'after': current
        })
    return trace

